package com.nthexperience.desktop;
import java.util.*;
public final class TenPolishCheck {
 public static void main(String[] args){Random random=new Random(20);int checked=0;for(int columns:new int[]{4,6})for(int pass=0;pass<300;pass++){List<String> sizes=new ArrayList<>();for(int i=0;i<32;i++)sizes.add(TenTileLayout.SIZES[random.nextInt(4)]);List<TenTileLayout.Cell> cells=TenTileLayout.place(sizes,columns);Set<Integer> used=new HashSet<>();for(TenTileLayout.Cell c:cells){if(c.col<0||c.col+c.w>columns)throw new AssertionError("Tile bounds");for(int y=c.row;y<c.row+c.h;y++)for(int x=c.col;x<c.col+c.w;x++)if(!used.add(y*columns+x))throw new AssertionError("Tile overlap");checked++;}}Set<String> ids=new HashSet<>(),categories=new HashSet<>();for(String[] c:TenSettingsCatalog.CATEGORIES)categories.add(c[0]);for(TenSettingsCatalog.Page p:TenSettingsCatalog.PAGES){if(!ids.add(p.id)||!categories.contains(p.category)||TenSettingsCatalog.page(p.id)!=p)throw new AssertionError("Settings destination");}if(TenSettingsCatalog.search("CLIPBOARD").stream().noneMatch(p->p.id.equals("clipboard")))throw new AssertionError("Settings search");for(String denied:new String[]{"SAFETY","CANCELLED","INVALID_REQUEST","CONTEXT_TOO_LONG"})if(TenAiPolicy.fallback(denied))throw new AssertionError("Disallowed cloud fallback");for(String allowed:new String[]{"UNAVAILABLE","TIMEOUT","RATE_LIMIT","BUSY","MODEL_NEEDED"})if(!TenAiPolicy.fallback(allowed))throw new AssertionError("Missing fallback");String proofread=TenWritingPrompts.build("proofread","The desktop are ready.");if(!proofread.contains("Return only the corrected passage")||!proofread.contains("The desktop are ready."))throw new AssertionError("Proofreading task instructions");if(TenWritingPrompts.build("polish","x".repeat(TenWritingPrompts.MAX_COMPOSER)).length()>16000)throw new AssertionError("Cloud prompt bound");System.out.println("PASS: "+checked+" mixed-size tiles, "+ids.size()+" searchable Settings destinations and local/cloud routing policy");}
}
